bounded_host_request.command:
set -euo pipefail
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import {readPrivateToken} from '/opt/videobot/src/runtime/config.mjs';
import {createTelegramBotApi} from '/opt/videobot/src/telegram/botApi.mjs';
import {createCreatorTelegramFetch} from '/opt/videobot/src/runtime/creatorEgress.mjs';
const outbound=createCreatorTelegramFetch();
try {
 const e=process.env,api=createTelegramBotApi({token:readPrivateToken(e.VIDEOBOT_TELEGRAM_TOKEN_FILE),fetchImpl:outbound.fetch,timeoutMs:25000,baseUrl:e.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org'});
 const chat_id=-1002373696859;
 try{const chat=await api('getChat',{chat_id});console.log('VIDEO_SALE_BOARD_TYPE='+chat.type+' IS_FORUM='+Boolean(chat.is_forum))}catch{console.log('VIDEO_SALE_BOARD_CHAT_API=ERROR')}
 try{const admins=await api('getChatAdministrators',{chat_id});
 const owner=admins.find(x=>x.status==='creator'||x.status==='owner'); const m=admins.find(x=>x.user?.id===788044853);
 console.log('BOARD_ADMIN_COUNT='+admins.length);console.log('MASTER_ROLE_BY_KNOWN_ID='+(m?.status??'not_admin'));console.log('MASTER_IS_BOARD_OWNER='+Boolean(owner?.user?.id===788044853));console.log('BOT_ADMIN_COUNT='+admins.filter(x=>x.user?.is_bot).length)
 }catch{console.log('VIDEO_SALE_BOARD_ADMIN_API=ERROR')}
}finally{await outbound.close()}
JS
